def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    chars = {ch: i for i, ch in enumerate(alphabet)}
    k = len(alphabet)

    transitions = [[-1] * k]
    terminal = [False]

    for word in banned:
        state = 0
        for ch in word:
            c = chars[ch]
            nxt = transitions[state][c]
            if nxt == -1:
                nxt = len(transitions)
                transitions[state][c] = nxt
                transitions.append([-1] * k)
                terminal.append(False)
            state = nxt
        terminal[state] = True

    fail = [0] * len(transitions)
    queue = []

    for c in range(k):
        child = transitions[0][c]
        if child == -1:
            transitions[0][c] = 0
        else:
            queue.append(child)

    head = 0
    while head < len(queue):
        state = queue[head]
        head += 1

        terminal[state] |= terminal[fail[state]]
        for c in range(k):
            child = transitions[state][c]
            if child == -1:
                transitions[state][c] = transitions[fail[state]][c]
            else:
                fail[child] = transitions[fail[state]][c]
                queue.append(child)

    safe_states = [i for i, is_terminal in enumerate(terminal) if not is_terminal]
    index = {state: i for i, state in enumerate(safe_states)}
    size = len(safe_states)

    matrix = [[0] * size for _ in range(size)]
    for state in safe_states:
        i = index[state]
        for c in range(k):
            nxt = transitions[state][c]
            if not terminal[nxt]:
                j = index[nxt]
                matrix[i][j] += 1

    vector = [0] * size
    vector[index[0]] = 1

    def multiply_matrices(a, b):
        result = [[0] * size for _ in range(size)]
        for i, row in enumerate(a):
            out = result[i]
            for mid, x in enumerate(row):
                if x:
                    brow = b[mid]
                    for j, y in enumerate(brow):
                        if y:
                            out[j] = (out[j] + x * y) % MOD
        return result

    def multiply_vector(v, a):
        result = [0] * size
        for i, x in enumerate(v):
            if x:
                for j, y in enumerate(a[i]):
                    if y:
                        result[j] = (result[j] + x * y) % MOD
        return result

    while n:
        if n & 1:
            vector = multiply_vector(vector, matrix)
        n >>= 1
        if n:
            matrix = multiply_matrices(matrix, matrix)

    return sum(vector) % MOD
